import {
  mkdirSync,
  cpSync,
  readdirSync,
  existsSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { resolve, join, dirname, basename } from "node:path";
const root = resolve(import.meta.dirname, ".."),
  out = join(root, "site");
if (dirname(out) !== root || out === root)
  throw Error("Invalid output directory");
if (existsSync(out)) {
  if (!existsSync(join(out, ".generated-arcade")))
    throw Error(
      "Refusing to overwrite a directory not generated by this build",
    );
  for (const item of readdirSync(out)) {
    try {
      rmSync(join(out, item), { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
    } catch (e) {}
  }
} else {
  mkdirSync(out);
}
writeFileSync(join(out, ".generated-arcade"), "Generated arcade build");
for (const f of readdirSync(root))
  if (/\.(html|png|ico|txt)$/.test(f) || ["CNAME", ".nojekyll"].includes(f))
    cpSync(join(root, f), join(out, f));
cpSync(join(root, "soul-ember/dist"), join(out, "soul-ember"), {
  recursive: true,
});
cpSync(join(root, "soul-ember/dist"), join(out, "soul_ember"), {
  recursive: true,
});
for (const name of ["road-riot", "dev-tycoon", "dead-signal", "assets"])
  if (existsSync(join(root, name)))
    cpSync(join(root, name), join(out, name), {
      recursive: true,
      filter: (source) =>
        !basename(source).startsWith(".") &&
        basename(source) !== "node_modules",
    });
// Road Riot imports the local Three.js distribution; keep its existing URLs working.
cpSync(join(root, "node_modules/three"), join(out, "node_modules/three"), {
  recursive: true,
});
console.log("Arcade production files written to site/");
